      if (isFinite(x) && isFinite(y)) pts.push([x, y]);
    }
    return pts;
  }

  /* ---------- right panel ---------- */
  function drawRight(g) {
    var u0 = state.u0, v0 = state.v0, d = state.d, tail = 0.45 * d, N = 44;
    var cU0 = sampleCurve(u0, 'u', v0 - tail, v0 + d + tail, N);
    var cU1 = sampleCurve(u0 + d, 'u', v0 - tail, v0 + d + tail, N);
    var cV0 = sampleCurve(v0, 'v', u0 - tail, u0 + d + tail, N);
    var cV1 = sampleCurve(v0 + d, 'v', u0 - tail, u0 + d + tail, N);

    var edge = [].concat(
      sampleCurve(v0, 'v', u0, u0 + d, N),
      sampleCurve(u0 + d, 'u', v0, v0 + d, N),
      sampleCurve(v0 + d, 'v', u0 + d, u0, N),
      sampleCurve(u0, 'u', v0 + d, v0, N));

    var all = cU0.concat(cU1, cV0, cV1, edge, [[0, 0]]);
    if (all.length < 6) {
      label(g, 'Transformation produced no finite values here', (RX0 + RX1) / 2, (RY0 + RY1) / 2, 'middle', 13, false, '#c00');
      return null;
    }
    var bx0 = Infinity, bx1 = -Infinity, by0 = Infinity, by1 = -Infinity;
    all.forEach(function (p) {
      if (p[0] < bx0) bx0 = p[0]; if (p[0] > bx1) bx1 = p[0];
      if (p[1] < by0) by0 = p[1]; if (p[1] > by1) by1 = p[1];
    });
    var bw = Math.max(1e-6, bx1 - bx0), bh = Math.max(1e-6, by1 - by0);
    bx0 -= bw * 0.07; bx1 += bw * 0.07; by0 -= bh * 0.07; by1 += bh * 0.07;
    bw = bx1 - bx0; bh = by1 - by0;
    var s = Math.min((RX1 - RX0) / bw, (RY1 - RY0) / bh);
    var cx = (RX0 + RX1) / 2, cy = (RY0 + RY1) / 2, mx = (bx0 + bx1) / 2, my = (by0 + by1) / 2;
    function Px(x) { return cx + (x - mx) * s; }
    function Py(y) { return cy - (y - my) * s; }
    function scr(pts) { return pts.map(function (p) { return [Px(p[0]), Py(p[1])]; }); }

    // axes
    var ax = clamp(Py(0), 24, H - 14), ay = clamp(Px(0), 604, W - 20);
    g.line(600, ax, 1002, ax).stroke({ color: BLACK, width: 1.7 });
    arrowTip(g, 1010, ax, 0, 10, BLACK);
    g.line(ay, H - 8, ay, 30).stroke({ color: BLACK, width: 1.7 });
    arrowTip(g, ay, 22, -Math.PI / 2, 10, BLACK);
    label(g, 'x', 990, ax - 15, 'middle', 16, true);
    label(g, 'y', ay + 14, 26, 'middle', 16, true);

    // region R
    var ePts = scr(edge);
    if (ePts.length > 3) {
      var poly = g.polygon(ePts).fill({ color: FILL, opacity: 0.85 }).stroke('none');
      poly.css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('R = T(S)', e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('The image region R', 'R is what the rectangle S becomes under T. Its edges are curves, and its area is generally NOT Δu·Δv — it is stretched (or squeezed) by the local factor |∂(x,y)/∂(u,v)|.');
        });
    }

    // image curves
    var curves = [
      { pts: cU0, name: 'Image of u = u₀', end: cU0[cU0.length - 1] },
      { pts: cU1, name: 'Image of u = u₀ + Δu', end: cU1[cU1.length - 1] },
      { pts: cV1, name: 'Image of v = v₀ + Δv', end: cV1[cV1.length - 1] },
      { pts: cV0, name: 'Image of v = v₀', end: cV0[cV0.length - 1] }
    ];
    curves.forEach(function (c) {
      if (c.pts.length < 2) return;
      g.polyline(scr(c.pts)).fill('none')
        .stroke({ color: BLUE, width: 3.2, linecap: 'round', linejoin: 'round' })
        .css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip(c.name, e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup(c.name, 'A straight grid line of the uv-plane is carried by T to this curve. The four image curves bound R, which is why R has curved sides even though S is a rectangle.');
        });
    });

    // curve labels with collision-aware placement
    var placed = [];
    function put(txt, px, py) {
      var size = 14, w = txt.length * size * 0.50, h = size + 6;
      var anchor, x;
      if (px >= (RX0 + RX1) / 2) { anchor = 'start'; x = px + 12; if (x + w > W - 6) { anchor = 'end'; x = Math.min(px - 12, W - 6); } }
      else { anchor = 'end'; x = px - 12; if (x - w < 600) { anchor = 'start'; x = px + 12; } }
      var offs = [0, -20, 20, -40, 40, -60, 60, -80, 80], y = clamp(py, 18, H - 16);
      for (var k = 0; k < offs.length; k++) {
        var yy = clamp(y + offs[k], 18, H - 16);
        var x0 = anchor === 'start' ? x : x - w, x1 = x0 + w;
        var hit = false;
        for (var j = 0; j < placed.length; j++) {
          var b = placed[j];
          if (x1 > b[0] && x0 < b[2] && yy + h / 2 > b[1] && yy - h / 2 < b[3]) { hit = true; break; }
        }
        if (!hit) { y = yy; break; }
      }
      var X0 = anchor === 'start' ? x : x - w;
      placed.push([X0, y - h / 2, X0 + w, y + h / 2]);
      g.line(px, py, anchor === 'start' ? x - 3 : x + 3, y).stroke({ color: '#aaa', width: 0.8 });
      g.circle(4).center(px, py).fill(BLUE);
      label(g, txt, x, y, anchor, size, false, '#000');
    }
    curves.forEach(function (c) { if (c.end) put(c.name, Px(c.end[0]), Py(c.end[1])); });

    // label R at centroid
    var gx = 0, gy = 0;
    edge.forEach(function (p) { gx += p[0]; gy += p[1]; });
    gx /= edge.length; gy /= edge.length;
    label(g, 'R', Px(gx), Py(gy), 'middle', 18, true);

    // Jacobian data
    var h = 1e-4 * Math.max(1, Math.abs(u0), Math.abs(v0));
    var xu = (safe(state.X, u0 + h, v0) - safe(state.X, u0 - h, v0)) / (2 * h);
    var yu = (safe(state.Y, u0 + h, v0) - safe(state.Y, u0 - h, v0)) / (2 * h);
    var xv = (safe(state.X, u0, v0 + h) - safe(state.X, u0, v0 - h)) / (2 * h);
    var yv = (safe(state.Y, u0, v0 + h) - safe(state.Y, u0, v0 - h)) / (2 * h);
    var J = xu * yv - xv * yu;
    var area = 0;
    for (var i = 0; i < edge.length; i++) {
      var p = edge[i], q = edge[(i + 1) % edge.length];
      area += p[0] * q[1] - q[0] * p[1];
    }
    area = Math.abs(area) / 2;

    if (state.overlay && isFinite(J)) {
      var p0 = [safe(state.X, u0, v0), safe(state.Y, u0, v0)];
      var A = [xu * d, yu * d], B = [xv * d, yv * d];
      var q1 = [p0[0] + A[0], p0[1] + A[1]], q2 = [p0[0] + B[0], p0[1] + B[1]];
      var q3 = [p0[0] + A[0] + B[0], p0[1] + A[1] + B[1]];
      g.polygon(scr([p0, q1, q3, q2])).fill({ color: ORANGE, opacity: 0.10 })
        .stroke({ color: ORANGE, width: 1.6, dasharray: '6,4', linejoin: 'round' });
      [[q1, 'Tᵤ Δu'], [q2, 'Tᵥ Δv']].forEach(function (o) {
        var x1 = Px(p0[0]), y1 = Py(p0[1]), x2 = Px(o[0][0]), y2 = Py(o[0][1]);
        var ang = Math.atan2(y2 - y1, x2 - x1);
        g.line(x1, y1, x2 - 7 * Math.cos(ang), y2 - 7 * Math.sin(ang)).stroke({ color: ORANGE, width: 2.4, linecap: 'round' });
        arrowTip(g, x2, y2, ang, 10, ORANGE);
        label(g, o[1], x2 + 10 * Math.cos(ang), y2 + 10 * Math.sin(ang), 'middle', 12, true, ORANGE);
      });
      g.circle(8).center(Px(p0[0]), Py(p0[1])).fill(ORANGE);

      // readout panel
      var bx = 444, by = 16, bwid = 164, bhi = 70;
      g.rect(bwid, bhi).move(bx, by).radius(4).fill('#ffffff').stroke({ color: '#bbb', width: 1 })
        .css('cursor', 'pointer')
        .on('click', function () {
          showPopup('Why the Jacobian?', 'The tangent vectors Tᵤ·Δu and Tᵥ·Δv span a parallelogram of area |xᵤyᵥ − xᵥyᵤ|·Δu·Δv = |J|·Δu·Δv. As Δu, Δv → 0 the curved region R becomes this parallelogram, so dA = |J| du dv inside a transformed double integral.');
        });
      var rows = ['Δu·Δv = ' + (d * d).toFixed(3),
      '|J(u₀,v₀)| = ' + Math.abs(J).toFixed(3),
      '|J|·Δu·Δv = ' + (Math.abs(J) * d * d).toFixed(3),
      'area(R) ≈ ' + area.toFixed(3)];
      rows.forEach(function (r, i) { label(g, r, bx + 9, by + 13 + i * 15, 'start', 11, false, '#333'); });
    }
    return { J: J, area: area };
  }

  /* ---------- render ---------- */
  function render() {
    if (!state.X || !state.Y) return;
    gDyn.clear();
    drawLeft(gDyn);
    var info = drawRight(gDyn);
    var el = document.getElementById('jacReadout');
    if (el) {
      var d = state.d;
      if (info && isFinite(info.J)) {
        el.innerHTML = 'Δu·Δv = ' + (d * d).toFixed(3) + '<br>|J(u₀,v₀)| = ' + Math.abs(info.J).toFixed(3) +
          '<br>|J|·Δu·Δv = ' + (Math.abs(info.J) * d * d).toFixed(3) +
          '<br>area(R) ≈ ' + info.area.toFixed(3) +
          '<br>(u₀, v₀) = (' + state.u0.toFixed(2) + ', ' + state.v0.toFixed(2) + ')';
      } else {
        el.textContent = 'no finite values';
      }
    }
  }

  /* ---------- controls ---------- */
  window.update_shrinkRectangle = function (v) {
    state.d = v;
    state.u0 = Math.min(state.u0, 2.45 - v);
    state.v0 = Math.min(state.v0, 2.5 - v);
    render();
  };
  window.toggle_showJacobian = function (on) { state.overlay = on; render(); };

  /* ---------- dragging ---------- */
  var dragMode = null;
  function toVB(e) {
    var p = svgNode.createSVGPoint(); p.x = e.clientX; p.y = e.clientY;
    return p.matrixTransform(svgNode.getScreenCTM().inverse());
  }
  document.addEventListener('mousemove', function (e) {
    if (!dragMode) return;
    var p = toVB(e), u = (p.x - OX) / SU, v = (OY - p.y) / SV;
    if (dragMode === 'move') {
      state.u0 = clamp(u, 0.2, 2.45 - state.d);
      state.v0 = clamp(v, 0.15, 2.5 - state.d);
    } else {
      var nd = clamp(Math.max(u - state.u0, v - state.v0), 0.05, 1.5);
      nd = Math.round(nd / 0.05) * 0.05;
      state.d = nd;
      state.u0 = Math.min(state.u0, 2.45 - nd);
      state.v0 = Math.min(state.v0, 2.5 - nd);
      document.getElementById('shrinkRectangleInput').value = nd;
      document.getElementById('shrinkRectangleVal').value = nd.toFixed(2);
    }
    render();
  });
  document.addEventListener('mouseup', function () { dragMode = null; });

  /* ---------- equation inputs ---------- */
  var eqX = bindEquationInput('xuvInput', function (fn) { state.X = fn; render(); }, { variables: ['u', 'v'] });
  var eqY = bindEquationInput('yuvInput', function (fn) { state.Y = fn; render(); }, { variables: ['u', 'v'] });

  /* ---------- demo steps ---------- */
  var steps = [
    {
      t: 'The rectangle S', n: 'In the uv-plane, the four grid lines u = u₀, u = u₀+Δu, v = v₀, v = v₀+Δv cut out a simple rectangle S of area Δu·Δv. Everything about it is easy to measure.',
      s: { u0: 1.4, v0: 0.5, d: 1, o: false, x: 'u*cos(v)', y: 'u*sin(v)' }
    },
    {
      t: 'Its image R', n: 'T sends each of those four straight lines to a curve in the xy-plane, and S to the curved quadrilateral R. With x = u cos v, y = u sin v the rectangle becomes a polar "fan" — straight edges bend.',
      s: { u0: 1.4, v0: 0.5, d: 1, o: false, x: 'u*cos(v)', y: 'u*sin(v)' }
    },
    {
      t: 'Move the rectangle', n: 'Drag the corners of S (or watch it jump here). The same-sized rectangle produces a much bigger image far from the origin than near it — the stretching is local, not global.',
      s: { u0: 2.2, v0: 0.9, d: 1, o: false, x: 'u*cos(v)', y: 'u*sin(v)' }
    },
    {
      t: 'Shrink it', n: 'Reduce Δu and Δv. The curved edges of R flatten out and R starts to look like a genuine parallelogram.',
      s: { u0: 2.2, v0: 0.9, d: 0.2, o: false, x: 'u*cos(v)', y: 'u*sin(v)' }
    },
    {
      t: 'The Jacobian appears', n: 'Overlay the tangent vectors at the corner: their parallelogram has area |∂(x,y)/∂(u,v)|·Δu·Δv, which now matches area(R) almost exactly. That determinant is the local area-stretch factor.',
      s: { u0: 2.2, v0: 0.9, d: 0.2, o: true, x: 'u*cos(v)', y: 'u*sin(v)' }
    },
    {
      t: 'Change the map', n: 'Type a different transformation: x = u*u - v*v, y = 2*u*v. The rectangle is unchanged, but R — and the Jacobian readout — change completely. Edit the fields yourself to explore.',
      s: { u0: 1.4, v0: 0.5, d: 0.4, o: true, x: 'u*u - v*v', y: '2*u*v' }
    }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = ((i % steps.length) + steps.length) % steps.length;
    var st = steps[cur].s;
    state.u0 = st.u0; state.v0 = st.v0; state.d = st.d; state.overlay = st.o;
    document.getElementById('shrinkRectangleInput').value = st.d;
    document.getElementById('shrinkRectangleVal').value = st.d;
    document.getElementById('showJacobianInput').checked = st.o;
    var xi = document.getElementById('xuvInput'), yi = document.getElementById('yuvInput');
    if (xi.value !== st.x) { xi.value = st.x; eqX.apply(st.x); }
    if (yi.value !== st.y) { yi.value = st.y; eqY.apply(st.y); }
    document.getElementById('demoNarration').textContent = steps[cur].n;
    document.getElementById('stepLabel').textContent = (cur + 1) + '/' + steps.length + ' · ' + steps[cur].t;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

