    { el: g.line(xL - over - 4, yT, xR + over + 4, yT), tip: 'v = v₀ + Δv' }
    ].forEach(function (o) {
      o.el.stroke({ color: BLUE, width: 3.4, linecap: 'round' }).css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip(o.tip, e); }).on('mouseleave', hideTooltip);
    });

    [[xL, yB], [xR, yB], [xL, yT], [xR, yT]].forEach(function (p) {
      g.circle(10).center(p[0], p[1]).fill(BLUE).stroke({ color: '#fff', width: 1 });
    });

    var hMove = g.circle(24).center(xL, yB).fill('#fff').opacity(0.001).css('cursor', 'move');
    var hSize = g.circle(24).center(xR, yT).fill('#fff').opacity(0.001).css('cursor', 'nwse-resize');
    hMove.on('mousedown', function (e) { e.preventDefault(); dragMode = 'move'; });
    hSize.on('mousedown', function (e) { e.preventDefault(); dragMode = 'size'; });
    hMove.on('mousemove', function (e) { showTooltip('Drag to move (u₀, v₀)', e); }).on('mouseleave', hideTooltip);
    hSize.on('mousemove', function (e) { showTooltip('Drag to resize Δu = Δv', e); }).on('mouseleave', hideTooltip);

    /* --- labels above the two vertical lines --- */
    var topY = yT - over - 22;
    var LX = xL + 26, RX = xR - 26;
    if (RX < LX + 16) { var mid = (xL + xR) / 2; LX = mid - 8; RX = mid + 8; }
    mathText(g, [['u = u', 1], ['₀', 1]], LX, topY, 'end', 20);
    mathText(g, [['u = u', 1], ['₀', 1], [' + ', 0], ['Δu', 1]], RX, topY, 'start', 20);

    /* --- labels right of the two horizontal lines --- */
    var lx = xR + over + 6, yTop = yT, yBot = yB;
    if (yBot - yTop < 28) { var m2 = (yT + yB) / 2; yTop = m2 - 14; yBot = m2 + 14; }
    mathText(g, [['v = v', 1], ['₀', 1], [' + ', 0], ['Δv', 1]], lx, yTop, 'start', 20);
    mathText(g, [['v = v', 1], ['₀', 1]], lx, yBot, 'start', 20);

    mathText(g, [['(u', 1], ['₀', 1], [', v', 1], ['₀', 1], [')', 1]], xL - 12, yB + 26, 'end', 20);
    mathText(g, [['Δu', 1]], (xL + xR) / 2, yB + 24, 'middle', 20);
    mathText(g, [['Δv', 1]], xR + 8, (yT + yB) / 2, 'start', 20);
    mathText(g, [['S', 1]], (xL + xR) / 2, (yT + yB) / 2, 'middle', 26);
  }

  /* ---------- sampling ---------- */
  function sampleCurve(fixed, which, a, b, n) {
    var pts = [];
    for (var i = 0; i <= n; i++) {
      var t = a + (b - a) * i / n;
      var u = which === 'u' ? fixed : t, v = which === 'u' ? t : fixed;
      var x = safe(state.X, u, v), y = safe(state.Y, u, v);
      if (isFinite(x) && isFinite(y)) pts.push([x, y]);
    }
    return pts;
  }

  /* ---------- right panel ---------- */
  function drawRight(g) {
    var u0 = state.u0, v0 = state.v0, d = state.d, tail = 0.4 * d, N = 48;
    var cU0 = sampleCurve(u0, 'u', v0 - tail, v0 + d + tail, N);
    var cU1 = sampleCurve(u0 + d, 'u', v0 - tail, v0 + d + tail, N);
    var cV0 = sampleCurve(v0, 'v', u0 - tail, u0 + d + tail, N);
    var cV1 = sampleCurve(v0 + d, 'v', u0 - tail, u0 + d + tail, N);
    var edge = [].concat(
      sampleCurve(v0, 'v', u0, u0 + d, N),
      sampleCurve(u0 + d, 'u', v0, v0 + d, N),
      sampleCurve(v0 + d, 'v', u0 + d, u0, N),
      sampleCurve(u0, 'u', v0 + d, v0, N));

    var all = cU0.concat(cU1, cV0, cV1, edge, [[0, 0]]);
    if (all.length < 10 || edge.length < 6) {
      sansText(g, 'transformation has no finite values here', (RB.x0 + RB.x1) / 2, (RB.y0 + RB.y1) / 2, 'middle', 15, '#c00');
      return null;
    }
    var bx0 = Infinity, bx1 = -Infinity, by0 = Infinity, by1 = -Infinity;
    all.forEach(function (p) {
      if (p[0] < bx0) bx0 = p[0]; if (p[0] > bx1) bx1 = p[0];
      if (p[1] < by0) by0 = p[1]; if (p[1] > by1) by1 = p[1];
    });
    var bw = Math.max(1e-9, bx1 - bx0), bh = Math.max(1e-9, by1 - by0);
    bx0 -= bw * 0.06; bx1 += bw * 0.06; by0 -= bh * 0.06; by1 += bh * 0.06;
    bw = bx1 - bx0; bh = by1 - by0;
    var s = Math.min((RB.x1 - RB.x0) / bw, (RB.y1 - RB.y0) / bh);
    var cx = (RB.x0 + RB.x1) / 2, cy = (RB.y0 + RB.y1) / 2;
    var mx = (bx0 + bx1) / 2, my = (by0 + by1) / 2;
    function Px(x) { return cx + (x - mx) * s; }
    function Py(y) { return cy - (y - my) * s; }
    function scr(pts) { return pts.map(function (p) { return [Px(p[0]), Py(p[1])]; }); }

    /* axes */
    var ax = clamp(Py(0), 72, 300), ay = clamp(Px(0), 566, 900);
    g.line(550, ax, 984, ax).stroke({ color: BLACK, width: 2 });
    arrowTip(g, 994, ax, 0, 11, BLACK);
    g.line(ay, 322, ay, 46).stroke({ color: BLACK, width: 2 });
    arrowTip(g, ay, 36, -Math.PI / 2, 11, BLACK);
    mathText(g, [['x', 1]], 962, ax - 20, 'middle', 22);
    mathText(g, [['y', 1]], ay + 17, 46, 'middle', 22);

    /* region R */
    var ePts = scr(edge);
    g.polygon(ePts).fill({ color: FILL, opacity: 0.9 }).stroke('none')
      .css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('R = T(S)', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('The image region R', 'R is what the rectangle S becomes under T. Its edges are curves, and its area is generally NOT Δu·Δv — it is stretched (or squeezed) by the local factor |∂(x,y)/∂(u,v)|.');
      });

    var curves = [
      { pts: cU0, segs: [['Image of ', 0], ['u = u', 1], ['₀', 1]], name: 'Image of u = u₀' },
      { pts: cU1, segs: [['Image of ', 0], ['u = u', 1], ['₀', 1], [' + ', 0], ['Δu', 1]], name: 'Image of u = u₀ + Δu' },
      { pts: cV1, segs: [['Image of ', 0], ['v = v', 1], ['₀', 1], [' + ', 0], ['Δv', 1]], name: 'Image of v = v₀ + Δv' },
      { pts: cV0, segs: [['Image of ', 0], ['v = v', 1], ['₀', 1]], name: 'Image of v = v₀' }
    ];
    curves.forEach(function (c) {
      if (c.pts.length < 2) return;
      g.polyline(scr(c.pts)).fill('none')
        .stroke({ color: BLUE, width: 3.4, linecap: 'round', linejoin: 'round' })
        .css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip(c.name, e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup(c.name, 'A straight grid line of the uv-plane is carried by T to this curve. The four image curves bound R, which is why R has curved sides even though S is a rectangle.');
        });
    });

    /* ---- assign the four labels to the four reserved slots ---- */
    var ends = curves.map(function (c) {
      if (c.pts.length < 2) return null;
      return [[Px(c.pts[0][0]), Py(c.pts[0][1])],
      [Px(c.pts[c.pts.length - 1][0]), Py(c.pts[c.pts.length - 1][1])]];
    });
    function inner(j) {
      var sl = SLOTS[j];
      return [sl.a === 'start' ? sl.x + 60 : sl.x - 60, sl.y];
    }
    function bestEnd(i, j) {
      if (!ends[i]) return { d: 1e9, p: null };
      var q = inner(j), b = null, bd = 1e18;
      for (var k = 0; k < 2; k++) {
        var dx = ends[i][k][0] - q[0], dy = ends[i][k][1] - q[1];
        var dd = Math.sqrt(dx * dx + dy * dy);
        if (dd < bd) { bd = dd; b = ends[i][k]; }
      }
      return { d: bd, p: b };
    }
    var best = [0, 1, 2, 3], bestC = Infinity;
    for (var a1 = 0; a1 < 4; a1++) for (var b1 = 0; b1 < 4; b1++) {
      if (b1 === a1) continue;
      for (var c1 = 0; c1 < 4; c1++) {
        if (c1 === a1 || c1 === b1) continue;
        var d1 = 6 - a1 - b1 - c1, p = [a1, b1, c1, d1], cost = 0;
        for (var i2 = 0; i2 < 4; i2++) cost += bestEnd(i2, p[i2]).d;
        if (cost < bestC) { bestC = cost; best = p; }
      }
    }
    for (var i3 = 0; i3 < 4; i3++) {
      var sl = SLOTS[best[i3]], be = bestEnd(i3, best[i3]);
      var lab = mathText(g, curves[i3].segs, sl.x, sl.y, sl.a, 18);
      if (be.p && be.d > 88) {
        var ex = sl.a === 'start' ? lab.x1 + 5 : lab.x0 - 5;
        g.line(ex, sl.y, be.p[0], be.p[1])
          .stroke({ color: '#b6b6b6', width: 0.9 }).opacity(0.65).back();
      }
    }

    /* R label at centroid */
    var gx = 0, gy = 0;
    edge.forEach(function (p) { gx += p[0]; gy += p[1]; });
    gx /= edge.length; gy /= edge.length;
    mathText(g, [['R', 1]], Px(gx), Py(gy), 'middle', 26);

    /* Jacobian data */
    var h = 1e-4 * Math.max(1, Math.abs(u0), Math.abs(v0));
    var xu = (safe(state.X, u0 + h, v0) - safe(state.X, u0 - h, v0)) / (2 * h);
    var yu = (safe(state.Y, u0 + h, v0) - safe(state.Y, u0 - h, v0)) / (2 * h);
    var xv = (safe(state.X, u0, v0 + h) - safe(state.X, u0, v0 - h)) / (2 * h);
    var yv = (safe(state.Y, u0, v0 + h) - safe(state.Y, u0, v0 - h)) / (2 * h);
    var J = xu * yv - xv * yu;
    var area = 0;
    for (var i4 = 0; i4 < edge.length; i4++) {
      var p1 = edge[i4], q1 = edge[(i4 + 1) % edge.length];
      area += p1[0] * q1[1] - q1[0] * p1[1];
    }
    area = Math.abs(area) / 2;

    if (state.overlay && isFinite(J)) {
      var p0 = [safe(state.X, u0, v0), safe(state.Y, u0, v0)];
      var A = [xu * d, yu * d], B = [xv * d, yv * d];
      var qa = [p0[0] + A[0], p0[1] + A[1]], qb = [p0[0] + B[0], p0[1] + B[1]];
      var qc = [p0[0] + A[0] + B[0], p0[1] + A[1] + B[1]];
      g.polygon(scr([p0, qa, qc, qb])).fill({ color: ORANGE, opacity: 0.12 })
        .stroke({ color: ORANGE, width: 1.8, dasharray: '6,4', linejoin: 'round' });
      [[qa, 'Tᵤ Δu'], [qb, 'Tᵥ Δv']].forEach(function (o) {
        var x1 = Px(p0[0]), y1 = Py(p0[1]), x2 = Px(o[0][0]), y2 = Py(o[0][1]);
        var ang = Math.atan2(y2 - y1, x2 - x1);
        g.line(x1, y1, x2 - 8 * Math.cos(ang), y2 - 8 * Math.sin(ang))
          .stroke({ color: ORANGE, width: 2.6, linecap: 'round' });
        arrowTip(g, x2, y2, ang, 11, ORANGE);
        mathText(g, [[o[1], 1]], x2 + 16 * Math.cos(ang), y2 + 14 * Math.sin(ang), 'middle', 16, ORANGE);
      });
      g.circle(9).center(Px(p0[0]), Py(p0[1])).fill(ORANGE);

      var bx = 436, by = 58, bwid = 160, bhi = 100;
      g.rect(bwid, bhi).move(bx, by).radius(5).fill('#ffffff').stroke({ color: '#bbb', width: 1 })
        .css('cursor', 'pointer')
        .on('mousemove', function (e) { showTooltip('area(R) → |J|·Δu·Δv as Δu, Δv → 0', e); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Why the Jacobian?', 'The tangent vectors Tᵤ·Δu and Tᵥ·Δv span a parallelogram of area |xᵤyᵥ − xᵥyᵤ|·Δu·Δv = |J|·Δu·Δv. As Δu, Δv → 0 the curved region R becomes this parallelogram, so dA = |J| du dv inside a transformed double integral.');
        });
      var rows = ['Δu·Δv = ' + (d * d).toFixed(3),
      '|J(u₀,v₀)| = ' + Math.abs(J).toFixed(3),
      '|J|·Δu·Δv = ' + (Math.abs(J) * d * d).toFixed(3),
      'area(R) ≈ ' + area.toFixed(3)];
      rows.forEach(function (r, i) { sansText(g, r, bx + 10, by + 18 + i * 22, 'start', 12.5, '#333', true); });
    }
    return { J: J, area: area };
  }

  /* ---------- render ---------- */
  function render() {
    if (!state.X || !state.Y) return;
    gDyn.clear();
    drawLeft(gDyn);
    var info = drawRight(gDyn);
    var el = document.getElementById('jacReadout');
    if (el) {
      var d = state.d;
      if (info && isFinite(info.J)) {
        el.innerHTML = 'Δu·Δv = ' + (d * d).toFixed(3) +
          '<br>|J(u₀,v₀)| = ' + Math.abs(info.J).toFixed(3) +
          '<br>|J|·Δu·Δv = ' + (Math.abs(info.J) * d * d).toFixed(3) +
          '<br>area(R) ≈ ' + info.area.toFixed(3);
      } else { el.textContent = 'no finite values'; }
    }
  }

  /* ---------- controls ---------- */
  window.update_shrinkRectangle = function (v) {
    state.d = v;
    state.u0 = clamp(state.u0, U_MIN, U_MAX - v);
    state.v0 = clamp(state.v0, V_MIN, V_MAX - v);
    render();
  };
  window.toggle_showJacobian = function (on) { state.overlay = on; render(); };

  /* ---------- dragging ---------- */
  var dragMode = null;
  function toVB(e) {
    var p = svgNode.createSVGPoint(); p.x = e.clientX; p.y = e.clientY;
    return p.matrixTransform(svgNode.getScreenCTM().inverse());
  }
  document.addEventListener('mousemove', function (e) {
    if (!dragMode) return;
    var p = toVB(e), u = (p.x - OX) / SU, v = (OY - p.y) / SV;
    if (dragMode === 'move') {
      state.u0 = clamp(u, U_MIN, U_MAX - state.d);
      state.v0 = clamp(v, V_MIN, V_MAX - state.d);
    } else {
      var nd = clamp(Math.max(u - state.u0, v - state.v0), 0.05, 1.5);
      nd = Math.round(nd / 0.05) * 0.05;
      state.d = nd;
      state.u0 = clamp(state.u0, U_MIN, U_MAX - nd);
      state.v0 = clamp(state.v0, V_MIN, V_MAX - nd);
      document.getElementById('shrinkRectangleInput').value = nd;
      document.getElementById('shrinkRectangleVal').value = nd.toFixed(2);
    }
    render();
  });
  document.addEventListener('mouseup', function () { dragMode = null; });

  /* ---------- equation inputs ---------- */
  var eqX = bindEquationInput('xuvInput', function (fn) { state.X = fn; render(); }, { variables: ['u', 'v'] });
  var eqY = bindEquationInput('yuvInput', function (fn) { state.Y = fn; render(); }, { variables: ['u', 'v'] });

  /* ---------- demo steps ---------- */
  var steps = [
    {
      t: 'The rectangle S',
      n: 'In the uv-plane the grid lines u = u₀, u = u₀+Δu, v = v₀, v = v₀+Δv cut out a rectangle S of area Δu·Δv. Everything about it is easy to measure.',
      s: { u0: 1.4, v0: 0.8, d: 1, o: false, x: 'u*cos(v)', y: 'u*sin(v)' }
    },
    {
      t: 'Its image R',
      n: 'T sends each straight line to a curve, and S to the curved quadrilateral R. With x = u cos v, y = u sin v the rectangle becomes a polar "fan" — straight edges bend.',
      s: { u0: 1.4, v0: 0.8, d: 1, o: false, x: 'u*cos(v)', y: 'u*sin(v)' }
    },
    {
      t: 'Move the rectangle',
      n: 'Move S near u = 0 (drag the dots yourself too). The SAME rectangle now lands as a much smaller region: the stretching is local, not global.',
      s: { u0: 0.25, v0: 0.9, d: 1, o: false, x: 'u*cos(v)', y: 'u*sin(v)' }
    },
    {
      t: 'Shrink it',
      n: 'Reduce Δu and Δv. The curved edges of R flatten out and R starts to look like a genuine parallelogram.',
      s: { u0: 1.6, v0: 1.0, d: 0.2, o: false, x: 'u*cos(v)', y: 'u*sin(v)' }
    },
    {
      t: 'The Jacobian appears',
      n: 'Overlay the tangent vectors at the corner: their parallelogram has area |∂(x,y)/∂(u,v)|·Δu·Δv, which now matches area(R) almost exactly — the local area-stretch factor.',
      s: { u0: 1.6, v0: 1.0, d: 0.2, o: true, x: 'u*cos(v)', y: 'u*sin(v)' }
    },
    {
      t: 'Change the map',
      n: 'A different transformation: x = u²−v², y = 2uv. The rectangle is unchanged, but R and the Jacobian readout change completely. Edit the fields to explore.',
      s: { u0: 1.0, v0: 0.7, d: 0.4, o: true, x: 'u*u - v*v', y: '2*u*v' }
    }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = ((i % steps.length) + steps.length) % steps.length;
    var st = steps[cur].s;
    state.u0 = st.u0; state.v0 = st.v0; state.d = st.d; state.overlay = st.o;
    document.getElementById('shrinkRectangleInput').value = st.d;
    document.getElementById('shrinkRectangleVal').value = st.d;
    document.getElementById('showJacobianInput').checked = st.o;
    var xi = document.getElementById('xuvInput'), yi = document.getElementById('yuvInput');
    if (xi.value !== st.x) { xi.value = st.x; eqX.apply(st.x); }
    if (yi.value !== st.y) { yi.value = st.y; eqY.apply(st.y); }
    document.getElementById('demoNarration').textContent = steps[cur].n;
    document.getElementById('stepLabel').textContent = (cur + 1) + '/' + steps.length + ' · ' + steps[cur].t;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

