      state.v0 = clamp(v, 0.25, V_VIEW - state.d);
    } else {
      var nd = clamp(Math.max(u - state.u0, v - state.v0), DMIN, DMAX);
      nd = Math.round(nd / 0.05) * 0.05;
      state.d = nd;
      state.u0 = clamp(state.u0, 0.1, U_VIEW - nd);
      state.v0 = clamp(state.v0, 0.25, V_VIEW - nd);
      document.getElementById('shrinkRectangleInput').value = nd;
      document.getElementById('shrinkRectangleVal').value = nd.toFixed(2);
    }
    render();
  });
  document.addEventListener('mouseup', function () { dragMode = null; });

  /* ---------------- equation inputs ---------------- */
  layout();
  var eqX = bindEquationInput('xuvInput', function (fn) { state.X = fn; render(); }, { variables: ['u', 'v'] });
  var eqY = bindEquationInput('yuvInput', function (fn) { state.Y = fn; render(); }, { variables: ['u', 'v'] });

  document.addEventListener('fig-resize', function () { layout(); render(); });

  /* ---------------- demo steps ---------------- */
  var steps = [
    {
      t: 'The rectangle S',
